const required = ['evaluation_id','accuracy','relevance','clarity','instruction_following','completeness'];
const data = $json.body ?? $json;
const missing = required.filter((field) => data[field] === undefined || data[field] === null || data[field] === '');
const scoreFields = required.slice(1);
const invalidScores = scoreFields.filter((field) => { const n = Number(data[field]); return !Number.isFinite(n) || n < 1 || n > 5; });
const values = scoreFields.map((field) => Number(data[field]));
const overallScore = invalidScores.length === 0 ? Number((values.reduce((a,b) => a + b, 0) / values.length).toFixed(2)) : null;
const valid = missing.length === 0 && invalidScores.length === 0;
return [{ json: { evaluation_id: data.evaluation_id ?? null, valid, missing_fields: missing, invalid_scores: invalidScores, overall_score: overallScore, quality_status: valid && overallScore >= 3.5 ? 'PASS' : 'REVIEW', received_at: new Date().toISOString() } }];
